package com.nm.fragmentsclean.editorialIntelligenceContext.write.adapters.secondary.gateways.repositories;
import com.nm.fragmentsclean.editorialIntelligenceContext.write.businesslogic.gateways.GenerationExecutionRepository; import com.nm.fragmentsclean.editorialIntelligenceContext.write.businesslogic.models.GenerationExecution; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository; import java.sql.Timestamp;
@Repository public class JdbcGenerationExecutionRepository implements GenerationExecutionRepository { private final JdbcTemplate jdbc; public JdbcGenerationExecutionRepository(JdbcTemplate jdbc){this.jdbc=jdbc;} public void save(GenerationExecution e){jdbc.update("INSERT INTO editorial_generation_executions(execution_id,operation,model,input_tokens,output_tokens,estimated_cost,duration_millis,outcome,occurred_at) VALUES(?,?,?,?,?,?,?,?,?)",e.id(),e.operation(),e.model(),e.inputTokens(),e.outputTokens(),e.estimatedCost(),e.duration().toMillis(),e.outcome(),Timestamp.from(e.occurredAt()));} }
